-- Keep the existing objects in place and require the owner's session for reads.
update storage.buckets set public = false where id = 'avatars';

create policy private_avatar_owner_only on storage.objects as restrictive
for all to public
using (
  bucket_id <> 'avatars' or (
    (storage.foldername(name))[1] = (select auth.uid())::text
    and (select auth.jwt())->>'is_anonymous' = 'false'
  )
)
with check (
  bucket_id <> 'avatars' or (
    (storage.foldername(name))[1] = (select auth.uid())::text
    and (select auth.jwt())->>'is_anonymous' = 'false'
  )
);

-- Convert links generated by earlier versions, including the SDK's trailing '?'.
update public.profiles
set profile_picture = substring(split_part(profile_picture, '?', 1) from '/avatars/([^/]+/avatar\.[a-z]+)$')
where split_part(profile_picture, '?', 1) ~ (
  '^https?://[^/]+/storage/v1/object/public/avatars/' || id::text || '/avatar\.(jpg|png|gif|webp)$'
);

create or replace function sortleaf_private.sync_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.is_anonymous is not true then
    insert into public.profiles (id, name, last_name, telephone)
    values (new.id, new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'last_name',
            new.raw_user_meta_data->>'telephone')
    on conflict (id) do nothing;
  end if;
  return new;
end $$;

alter table public.profiles add constraint profile_picture_belongs_to_owner
check (profile_picture is null or profile_picture ~ ('^' || id::text || '/avatar\.(jpg|png|gif|webp)$'));
